SELECT * FROM settlement_rule


        AND rule_type = #{ruleType}


        AND business_type = #{businessType}


        AND is_enabled = #{isEnabled}


        AND org_id = #{orgId}


ORDER BY priority DESC, create_time DESC

SELECT * FROM settlement_rule
WHERE rule_type = #{ruleType} AND org_id = #{orgId}
ORDER BY priority DESC, create_time DESC

SELECT * FROM settlement_rule
WHERE business_type = #{businessType} AND org_id = #{orgId}
ORDER BY priority DESC, create_time DESC

SELECT * FROM settlement_rule
WHERE is_enabled = 1
AND org_id = #{orgId}
AND rule_id != #{ruleId}
AND rule_type = #{ruleType}
AND business_type = #{businessType}
AND (
    (effective_date IS NULL OR effective_date <= #{expireDate})
    AND (expire_date IS NULL OR expire_date >= #{effectiveDate})
)
ORDER BY priority DESC

SELECT rule_type, COUNT(*) as ruleCount, SUM(execution_count) as totalExecutions, SUM(success_count) as totalSuccesses, AVG(success_count * 100.0 / NULLIF(execution_count, 0)) as avgSuccessRate, MAX(last_execution_time) as lastExecutionTime FROM settlement_rule WHERE org_id = #{orgId} AND execution_count > 0
AND DATE(last_execution_time) >= #{startDate}
AND DATE(last_execution_time) <= #{endDate}
GROUP BY rule_type ORDER BY totalExecutions DESC

SELECT * FROM settlement_rule
WHERE org_id = #{orgId}
AND is_enabled = 1
AND priority >= #{minPriority}
ORDER BY priority DESC, create_time DESC
